<script setup lang="ts">
import {computed,inject,onUnmounted,ref,watch} from 'vue';
import {NAlert,NButton,NDrawer,NDrawerContent,NInput,NSelect,NSkeleton,useDialog} from 'naive-ui';
import {taskSpacesApi,type TaskSpace,type SpaceCreate,type SpaceTaskCreate} from '../api/task-spaces';
import {taskApi,type TaskRecord} from '../api/tasks';
import {agentsApi} from '../api/agents';
import {D2ApiError} from '../api/client';
import TaskDetailPanel from '../components/TaskDetailPanel.vue';
import {sessionStatus} from '../utils/session-presentation';
const props=defineProps<{workspace:string;readOnly?:boolean}>(),dialog=useDialog();
const emit=defineEmits<{openWork:[id:string]}>();
const spaces=ref<TaskSpace[]>([]),space=ref<TaskSpace|null>(null),tasks=ref<TaskRecord[]>([]),agents=ref<{label:string;value:string;disabled:boolean}[]>([]);
const listError=ref(''),detailError=ref(''),agentError=ref(''),writeError=ref(''),notice=ref('');
const loading=ref(false),detailLoading=ref(false),taskLoading=ref(false),busy=ref(false),denied=ref(false);
const next=ref<string|null>(null),cursor=ref(''),previous=ref<string[]>([]),taskNext=ref<string|null>(null),taskCursor=ref(''),taskPrevious=ref<string[]>([]),selectedTask=ref('');
const grantAgent=ref<string|null>(null);
const pendingRequest=ref(false),pendingTaskRequest=ref(false);
const businessKey=ref(''),initialAgent=ref<string|null>(null),taskAgent=ref<string|null>(null),taskTitle=ref(''),taskText=ref('');
let listRead=0,taskRead=0;let generation=0,detailGeneration=0,controller=new AbortController(),detailController=new AbortController();
let spaceRequest:{key:string;body:SpaceCreate}|null=null,taskRequest:{key:string;body:SpaceTaskCreate}|null=null;
const activeAgents=computed(()=>space.value?.agents.filter(a=>a.status==='active').map(a=>({value:a.agent_id,label:agents.value.find(v=>v.value===a.agent_id)?.label||a.agent_id}))||[]);
const canCreateTask=computed(()=>!!space.value&&space.value.lifecycle==='active'&&!denied.value&&!detailLoading.value&&!busy.value&&!!taskAgent.value&&activeAgents.value.some(a=>a.value===taskAgent.value));
const dirty=computed(()=>!!businessKey.value||!!taskText.value||!!taskTitle.value||pendingRequest.value);
function message(e:unknown){return e instanceof Error?e.message:'请求失败，请重试'}
function revoked(e:unknown){if(e instanceof D2ApiError&&[401,403].includes(e.status)){denied.value=true;++generation;++detailGeneration;controller.abort();detailController.abort();loading.value=false;detailLoading.value=false;taskLoading.value=false;busy.value=false;space.value=null;tasks.value=[];spaces.value=[];agents.value=[];selectedTask.value='';}}
async function list(){const g=generation,read=++listRead;loading.value=true;listError.value='';try{const r=await taskSpacesApi.list(props.workspace,cursor.value,controller.signal);if(g!==generation||read!==listRead)return;if(r.next_cursor&&(r.next_cursor===cursor.value||previous.value.includes(r.next_cursor)))throw new Error('空间分页游标重复，请重新读取');spaces.value=r.items;next.value=r.next_cursor}catch(e){if(g===generation){if(read!==listRead)return;listError.value=message(e);revoked(e)}}finally{if(g===generation&&read===listRead)loading.value=false}}
async function loadAgents(){const g=generation;agentError.value='';try{const rows:{label:string;value:string;disabled:boolean}[]=[],seen=new Set<string>();for(let p=1;p<=1000;p++){const r=await agentsApi.list(props.workspace,p,controller.signal);if(g!==generation)return;if(r.page!==p||r.items.some(v=>seen.has(v.id)))throw new Error('员工分页异常');r.items.forEach(v=>{seen.add(v.id);rows.push({value:v.id,label:v.name+(v.enabled?'':'（已停用）'),disabled:!v.enabled})});if(!r.items.length||rows.length>=r.total){agents.value=rows;return}}throw new Error('员工数量过多')}catch(e){if(g===generation){agentError.value=message(e);revoked(e)}}}
async function taskList(){if(!space.value)return;const g=generation,d=detailGeneration,read=++taskRead,id=space.value.id;taskLoading.value=true;detailError.value='';try{const r=await taskApi.list(props.workspace,{task_space_id:id},taskCursor.value,detailController.signal);if(g!==generation||d!==detailGeneration||read!==taskRead)return;if(r.items.some(v=>v.task_space_id!==id))throw new Error('任务归属不匹配，已停止展示');if(r.next_cursor&&(r.next_cursor===taskCursor.value||taskPrevious.value.includes(r.next_cursor)))throw new Error('任务分页游标重复');tasks.value=r.items;taskNext.value=r.next_cursor}catch(e){if(g===generation&&d===detailGeneration){if(read!==taskRead)return;detailError.value=message(e);tasks.value=[];revoked(e)}}finally{if(g===generation&&d===detailGeneration&&read===taskRead)taskLoading.value=false}}
async function open(id:string){if(denied.value)return;const previousAgent=space.value?.id===id?taskAgent.value:null;const g=generation,d=++detailGeneration;detailController.abort();detailController=new AbortController();space.value=null;tasks.value=[];selectedTask.value='';taskCursor.value='';taskPrevious.value=[];taskNext.value=null;taskAgent.value=null;detailLoading.value=true;detailError.value='';try{const r=await taskSpacesApi.get(props.workspace,id,detailController.signal);if(g!==generation||d!==detailGeneration)return;space.value=r;const options=r.agents.filter(a=>a.status==='active');if(previousAgent&&options.some(a=>a.agent_id===previousAgent))taskAgent.value=previousAgent;else if(options.length===1)taskAgent.value=options[0]!.agent_id;await taskList()}catch(e){if(g===generation&&d===detailGeneration){detailError.value=message(e);revoked(e)}}finally{if(g===generation&&d===detailGeneration)detailLoading.value=false}}
function changeSpace(id:string){if(busy.value||denied.value)return;const g=generation,d=detailGeneration;if(taskText.value||taskTitle.value||taskRequest){dialog.warning({title:'任务草稿尚未提交',content:'继续会放弃草稿；若此前请求响应丢失，请先重试原请求确认是否已受理。',positiveText:'放弃草稿并切换',negativeText:'保留草稿',onPositiveClick:()=>{if(g!==generation||d!==detailGeneration||denied.value)return;taskText.value='';taskTitle.value='';taskRequest=null;pendingTaskRequest.value=false;pendingRequest.value=!!spaceRequest;void open(id)}})}else void open(id)}
async function createSpace(){if(props.readOnly||busy.value||denied.value||!initialAgent.value)return;const body:SpaceCreate={agent_id:initialAgent.value,business_key:businessKey.value||null};if(!spaceRequest)spaceRequest={key:crypto.randomUUID(),body};pendingRequest.value=true;if(JSON.stringify(spaceRequest.body)!==JSON.stringify(body)){writeError.value='请求结果尚未确认，请恢复原字段后重试，或明确放弃该请求。';return}const g=generation;busy.value=true;writeError.value='';notice.value='';try{const r=await taskSpacesApi.create(props.workspace,body,spaceRequest.key,controller.signal);if(g!==generation)return;spaceRequest=null;pendingRequest.value=false;businessKey.value='';notice.value='任务空间已就绪；命中相同业务键不会创建重复空间。';cursor.value='';previous.value=[];await list();if(g!==generation||denied.value)return;await open(r.id)}catch(e){if(g===generation){writeError.value=message(e)+'；不会自动重试。同一内容再次提交沿用原幂等键。';revoked(e)}}finally{if(g===generation)busy.value=false}}
async function createTask(){if(props.readOnly||!canCreateTask.value||!space.value||!taskAgent.value||!taskText.value.trim())return;const body:SpaceTaskCreate={task_space_id:space.value.id,agent_id:taskAgent.value,mode:'task',title:taskTitle.value.trim()||null,input:{text:taskText.value}};if(!taskRequest)taskRequest={key:crypto.randomUUID(),body};pendingTaskRequest.value=true;pendingRequest.value=true;if(JSON.stringify(taskRequest.body)!==JSON.stringify(body)){writeError.value='任务请求结果尚未确认，请恢复原字段重试，或明确放弃该请求。';return}const g=generation,d=detailGeneration;busy.value=true;writeError.value='';notice.value='';try{const r=await taskSpacesApi.createTask(props.workspace,body,taskRequest.key,controller.signal);if(g!==generation||d!==detailGeneration)return;taskRequest=null;pendingTaskRequest.value=false;pendingRequest.value=false;taskText.value='';taskTitle.value='';notice.value='任务已受理，不代表执行完成。';taskCursor.value='';taskPrevious.value=[];await taskList();if(g!==generation||d!==detailGeneration||denied.value)return;if(r.task_id)selectedTask.value=r.task_id}catch(e){if(g===generation&&d===detailGeneration){writeError.value=message(e)+'；不会自动重试，原请求可用同一幂等键重试。';revoked(e)}}finally{if(g===generation)busy.value=false}}
function confirmGrant(agent:string,enabled:boolean){if(props.readOnly||!space.value||busy.value)return;const target={workspace:props.workspace,id:space.value.id,version:space.value.version,g:generation,d:detailGeneration};dialog.warning({title:enabled?'明确授权此员工':'撤销此员工授权',content:enabled?'仅授权所选员工在此空间创建和执行任务，不授权其他员工，不改变使用范围或能力包，也不绕过当前使用范围。':'撤销后服务器会拒绝该员工在此空间的新受理和执行。重新授权也不会恢复旧任务的继续输入；不影响其他员工。',positiveText:enabled?'确认授权':'确认撤销',negativeText:'取消',onPositiveClick:()=>{if(target.workspace!==props.workspace||target.g!==generation||target.d!==detailGeneration||target.id!==space.value?.id||target.version!==space.value?.version){writeError.value='空间或授权版本已变化，请重新确认操作。';return}return grant(agent,enabled)}})}
async function grant(agent:string,enabled:boolean){if(props.readOnly||!space.value||busy.value)return;const g=generation,d=detailGeneration,id=space.value.id,v=space.value.version;busy.value=true;writeError.value='';try{const r=await taskSpacesApi.grant(props.workspace,id,agent,v,enabled,detailController.signal);if(g!==generation||d!==detailGeneration)return;space.value=r;grantAgent.value=null;if(taskAgent.value&&!r.agents.some(a=>a.agent_id===taskAgent.value&&a.status==='active'))taskAgent.value=null;notice.value=enabled?'员工授权已保存。':'员工授权已撤销。'}catch(e){if(g===generation&&d===detailGeneration){writeError.value=message(e);revoked(e)}}finally{if(g===generation)busy.value=false}}
function abandon(){const g=generation;dialog.warning({title:'放弃未确认请求',content:'响应丢失时请求可能已成功。请先刷新列表核对；继续后再次提交会使用新幂等键，可能创建另一空间或任务。',positiveText:'放弃并清空草稿',negativeText:'保留原请求',onPositiveClick:()=>{if(g!==generation)return;spaceRequest=null;taskRequest=null;pendingTaskRequest.value=false;pendingRequest.value=false;businessKey.value='';taskTitle.value='';taskText.value='';writeError.value=''}})}
function paginate(forward:boolean,task=false){if(busy.value||loading.value||taskLoading.value)return;const c=task?taskCursor:cursor,n=task?taskNext:next,p=task?taskPrevious:previous;if(forward&&n.value){p.value.push(c.value);c.value=n.value}else if(!forward&&p.value.length)c.value=p.value.pop()||'';void(task?taskList():list())}
function reset(){++generation;++detailGeneration;controller.abort();detailController.abort();controller=new AbortController();detailController=new AbortController();spaces.value=[];space.value=null;tasks.value=[];agents.value=[];cursor.value='';next.value=null;previous.value=[];selectedTask.value='';taskCursor.value='';taskPrevious.value=[];taskNext.value=null;businessKey.value='';grantAgent.value=null;initialAgent.value=null;taskAgent.value=null;taskText.value='';taskTitle.value='';spaceRequest=null;taskRequest=null;pendingTaskRequest.value=false;pendingRequest.value=false;busy.value=false;denied.value=false;notice.value='';writeError.value='';detailError.value='';void list();void loadAgents()}
const draft={hasUnsaved:()=>dirty.value||busy.value,getLabel:()=> '任务空间草稿',save:async()=>false,discard:()=>{businessKey.value='';taskText.value='';taskTitle.value='';spaceRequest=null;taskRequest=null;pendingTaskRequest.value=false;pendingRequest.value=false}};const guard=inject<{register:(v:typeof draft)=>void;unregister:(v:typeof draft)=>void}>('d2DraftGuard');guard?.register(draft);
watch(()=>props.workspace,reset,{immediate:true});onUnmounted(()=>{++generation;++detailGeneration;controller.abort();detailController.abort();guard?.unregister(draft)});
defineExpose({refresh:list});
</script>
<template><section class="task-spaces" :class="{inspection:readOnly}"><header><div><h2>任务空间</h2><p>按业务键组织独立任务。每个任务拥有独立的执行环境和历史。</p></div><NButton :disabled="busy||loading" @click="list">刷新空间</NButton></header><NAlert v-if="denied" type="warning">当前访问权限不足或已变化。已隐藏空间与任务内容，请重新确认权限。</NAlert><NAlert v-if="listError" type="error">{{listError}}</NAlert><NAlert v-if="agentError" type="warning">{{agentError}} <NButton @click="loadAgents">重试员工列表</NButton></NAlert><NAlert v-if="writeError" type="error">{{writeError}} <NButton :disabled="busy" @click="abandon">放弃未确认请求</NButton></NAlert><NAlert v-if="notice" type="success">{{notice}}</NAlert><template v-if="!denied"><fieldset v-if="!readOnly"><legend>创建或按 businessKey 打开</legend><NInput v-model:value="businessKey" :disabled="busy" maxlength="200" placeholder="业务键（选填，留空创建独立空间）"/><NSelect :virtual-scroll="false" v-model:value="initialAgent" :disabled="busy" :options="agents" placeholder="选择初始执行员工" filterable/><p>同一工作区同一业务键唯一。知道业务键不代表有权限，也不会自动给其他员工授权；无业务键的每次新请求创建独立空间。</p><NButton type="primary" :loading="busy" :disabled="busy||!initialAgent||!!agentError||!!taskText||!!taskTitle||pendingTaskRequest" @click="createSpace">创建或打开空间</NButton></fieldset><NSkeleton v-if="loading&&!spaces.length" text :repeat="3"/><div v-else class="space-list"><article v-for="s in spaces" :key="s.id"><button class="link" :disabled="busy" @click="changeSpace(s.id)">{{s.business_key||'无业务键空间'}}</button><small>{{s.id}} · {{s.lifecycle}} · {{new Date(s.created_at).toLocaleString('zh-CN')}}</small></article><p v-if="!spaces.length&&!listError">暂无有权查看的任务空间。</p></div><nav><NButton :disabled="busy||loading||!previous.length" @click="paginate(false)">上一页空间</NButton><NButton :disabled="busy||loading||!next" @click="paginate(true)">下一页空间</NButton></nav><NAlert v-if="detailError" type="error">{{detailError}}</NAlert><p v-if="detailLoading">正在读取空间…</p><section v-if="space" class="space-detail"><header><div><h3>{{space.business_key||'无业务键空间'}}</h3><small>{{space.id}} · v{{space.version}}</small></div><NButton :disabled="busy||detailLoading" @click="open(space.id)">刷新当前空间</NButton></header><fieldset><legend>{{readOnly?'空间员工授权':'允许员工在此空间执行任务'}}</legend><p v-if="!readOnly">此设置只决定哪些员工可在这个任务空间执行任务，不改变员工使用范围或能力包。业务键命中或同属工作区不自动获得权限。</p><article v-for="a in space.agents" :key="a.agent_id"><span>{{agents.find(v=>v.value===a.agent_id)?.label||a.agent_id}} · {{a.status}}</span><NButton v-if="!readOnly && a.status==='active'" size="small" :disabled="busy" @click="confirmGrant(a.agent_id,false)">撤销授权</NButton></article><NSelect v-if="!readOnly" :virtual-scroll="false" v-model:value="grantAgent" :disabled="busy" :options="agents.filter(a=>!activeAgents.some(v=>v.value===a.value))" placeholder="选择需要明确授权的员工" filterable/><NButton v-if="!readOnly" :disabled="busy||!grantAgent||!!agentError" @click="grantAgent&&confirmGrant(grantAgent,true)">授权所选员工</NButton></fieldset><fieldset v-if="!readOnly"><legend>在此空间创建任务</legend><NSelect :virtual-scroll="false" v-model:value="taskAgent" :disabled="busy||detailLoading" :options="activeAgents" placeholder="选择此空间已授权的员工"/><NInput v-model:value="taskTitle" :disabled="busy" maxlength="200" placeholder="任务标题（选填）"/><NInput v-model:value="taskText" :disabled="busy" type="textarea" placeholder="本次任务要求"/><p>只使用此空间当前有效授权；服务器仍会校验账号、员工与模型权限。任务有独立 Session，不会创建或伪造来源对话。</p><p v-if="!activeAgents.length">当前没有已授权的执行员工，不能创建任务。</p><NButton type="primary" :disabled="!canCreateTask||!taskText.trim()" :loading="busy" @click="createTask">创建空间任务</NButton></fieldset><NButton :disabled="taskLoading||busy" @click="taskList">刷新空间任务</NButton><p v-if="taskLoading">正在读取任务…</p><article v-for="t in tasks" :key="t.task_id"><button class="link" @click="selectedTask=t.task_id">{{t.title||'未命名任务'}}</button><small>{{t.agent.name}} · {{sessionStatus(t.execution.state)}} · {{t.task_id}}</small></article><p v-if="!taskLoading&&!tasks.length&&!detailError">此空间暂无可见任务。</p><nav><NButton :disabled="busy||taskLoading||!taskPrevious.length" @click="paginate(false,true)">上一页任务</NButton><NButton :disabled="busy||taskLoading||!taskNext" @click="paginate(true,true)">下一页任务</NButton></nav></section></template><NDrawer :show="!!selectedTask&&!denied" :width="'min(760px,100vw)'" @update:show="v=>{if(!v)selectedTask=''}"><NDrawerContent :native-scrollbar="false" body-content-style="padding:0;height:100%"><TaskDetailPanel v-if="selectedTask&&!denied" :key="workspace+':'+selectedTask" :workspace-id="workspace" :task-id="selectedTask" :task-center="readOnly" presentation="drawer" @open-work="id=>emit('openWork',id)" @close="selectedTask=''" @task-changed="taskList"/></NDrawerContent></NDrawer></section></template>
<style scoped>.task-spaces{color:var(--id-text-primary);display:flex;flex-direction:column;gap:16px}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h2,h3{margin:0 0 8px}p,small{color:var(--id-text-muted);font-size:12px;line-height:1.7}fieldset,.space-detail{border:1px solid var(--id-border-subtle);border-radius:10px;padding:18px;min-width:0}fieldset{display:flex;flex-direction:column;gap:12px}fieldset>.n-button{align-self:flex-start}article{padding:14px 0;border-bottom:1px solid var(--id-border-subtle)}small{display:block;overflow-wrap:anywhere}.link{border:0;background:none;padding:0;color:var(--id-accent-primary);font:inherit;cursor:pointer;text-align:left;overflow-wrap:anywhere}nav{display:flex;justify-content:flex-end;gap:8px}.space-detail{display:flex;flex-direction:column;gap:12px}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}fieldset,.space-detail{padding:12px}}.inspection .space-list,.inspection .space-detail{background:var(--id-bg-surface);border:1px solid var(--id-border-subtle);border-radius:var(--id-radius-lg);padding:0 16px}.inspection .space-detail{padding:16px}.inspection .space-list article:last-child{border-bottom:0}
</style>
